import{_ as s,o as e,c as t,ak as i}from"./chunks/framework.DKi5cyCJ.js";const g=JSON.parse('{"title":"GitHub Pages 部署说明（当前正式方式）","description":"","frontmatter":{},"headers":[],"relativePath":"GitHub部署说明.md","filePath":"GitHub部署说明.md"}'),d={name:"GitHub部署说明.md"};function o(n,a,l,r,c,h){return e(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="github-pages-部署说明-当前正式方式" tabindex="-1">GitHub Pages 部署说明（当前正式方式） <a class="header-anchor" href="#github-pages-部署说明-当前正式方式" aria-label="Permalink to &quot;GitHub Pages 部署说明（当前正式方式）&quot;">​</a></h1><blockquote><p>本文记录 <strong>通过 GitHub 把个人博客发布到公网</strong> 的完整流程。<br> 域名：<strong>milkywaydev.cn</strong> / <strong>www.milkywaydev.cn</strong>（以你 DNS / Pages 实际绑定为准）<br> 仓库：<code>git@github.com:FridayIron/milkywaydev.git</code><br> 发布分支：<strong>main</strong>，GitHub Pages 站点目录：<strong>/docs</strong></p></blockquote><blockquote><p><strong>说明</strong>：仓库里的 <code>docs/</code> 是 <code>npm run deploy</code> 生成的<strong>静态网站成品</strong>，每次构建会整目录覆盖，不要手改里面的 HTML。<br> 本说明等 Markdown 写在<strong>项目根目录</strong>（与 <code>腾讯云部署说明.md</code> 同级），下次 <code>deploy</code> 后也会出现在站点里。</p></blockquote><hr><h2 id="一、整体原理-忘掉细节时先看这里" tabindex="-1">一、整体原理（忘掉细节时先看这里） <a class="header-anchor" href="#一、整体原理-忘掉细节时先看这里" aria-label="Permalink to &quot;一、整体原理（忘掉细节时先看这里）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>本地改 Markdown / 配置</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>  npm run deploy</span></span>
<span class="line"><span>  （VitePress 构建 → 复制到 docs/）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>  git add / commit / push 到 GitHub（必须包含 docs/）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>  GitHub Pages 读取 main 分支的 /docs</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>  公网可访问：https://milkywaydev.cn</span></span></code></pre></div><p>这是<strong>纯静态站</strong>：没有服务器跑 Node/Python。访客打开的是 GitHub 托管的 HTML/CSS/JS。</p><hr><h2 id="二、当前仓库与-pages-配置-已配好-一般不用再改" tabindex="-1">二、当前仓库与 Pages 配置（已配好，一般不用再改） <a class="header-anchor" href="#二、当前仓库与-pages-配置-已配好-一般不用再改" aria-label="Permalink to &quot;二、当前仓库与 Pages 配置（已配好，一般不用再改）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>当前值</th></tr></thead><tbody><tr><td>远程仓库</td><td><code>origin</code> → <code>git@github.com:FridayIron/milkywaydev.git</code></td></tr><tr><td>默认分支</td><td><code>main</code></td></tr><tr><td>Pages 来源</td><td>Deploy from a branch</td></tr><tr><td>Branch</td><td><code>main</code></td></tr><tr><td>Folder</td><td><code>/docs</code>（不是根目录 <code>/</code>）</td></tr><tr><td>自定义域名</td><td><code>milkywaydev.cn</code>（<code>docs/CNAME</code> / 根目录 <code>CNAME</code>）</td></tr><tr><td>站点 base</td><td><code>/</code>（见 <code>.vitepress/config.mjs</code> 的 <code>base: &#39;/&#39;</code>）</td></tr></tbody></table><h3 id="_2-1-在-github-网页上核对-很久没部署时建议看一眼" tabindex="-1">2.1 在 GitHub 网页上核对（很久没部署时建议看一眼） <a class="header-anchor" href="#_2-1-在-github-网页上核对-很久没部署时建议看一眼" aria-label="Permalink to &quot;2.1 在 GitHub 网页上核对（很久没部署时建议看一眼）&quot;">​</a></h3><ol><li>打开仓库：<a href="https://github.com/FridayIron/milkywaydev" target="_blank" rel="noreferrer">https://github.com/FridayIron/milkywaydev</a></li><li><strong>Settings → Pages</strong></li><li>确认： <ul><li>Source = <strong>Deploy from a branch</strong></li><li>Branch = <strong>main</strong></li><li>Folder = <strong>/docs</strong></li><li>Custom domain = <strong>milkywaydev.cn</strong>（若启用了 Enforce HTTPS，保持勾选）</li></ul></li></ol><h3 id="_2-2-域名-dns-换过域名商或-dns-时才需要" tabindex="-1">2.2 域名 DNS（换过域名商或 DNS 时才需要） <a class="header-anchor" href="#_2-2-域名-dns-换过域名商或-dns-时才需要" aria-label="Permalink to &quot;2.2 域名 DNS（换过域名商或 DNS 时才需要）&quot;">​</a></h3><p>GitHub Pages 自定义域名通常需要：</p><ul><li><strong>A 记录</strong> 指向 GitHub Pages IP（以 GitHub 官方文档当前列表为准），或</li><li><strong>CNAME</strong> 把 <code>www</code> / 根域指到 <code>FridayIron.github.io</code>（按你账号/仓库的 Pages 提示填写）</li></ul><p>根目录 / <code>docs/</code> 里的 <code>CNAME</code> 文件内容应为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>milkywaydev.cn</span></span></code></pre></div><p>若执行 <code>npm run deploy</code> 后发现 <code>docs/CNAME</code> 没了：把项目根目录的 <code>CNAME</code> 再复制进 <code>docs/</code>，或长期放到 <code>public/CNAME</code>（构建时会自动带进成品）。</p><hr><h2 id="三、日常更新上线-最常用-记住这-4-步" tabindex="-1">三、日常更新上线（最常用，记住这 4 步） <a class="header-anchor" href="#三、日常更新上线-最常用-记住这-4-步" aria-label="Permalink to &quot;三、日常更新上线（最常用，记住这 4 步）&quot;">​</a></h2><h3 id="_1-本地改内容" tabindex="-1">1. 本地改内容 <a class="header-anchor" href="#_1-本地改内容" aria-label="Permalink to &quot;1. 本地改内容&quot;">​</a></h3><p>例如改 <code>pages/*.md</code>、加工具、改 <code>.vitepress/config.mjs</code> 导航等。</p><h3 id="_2-构建到-docs" tabindex="-1">2. 构建到 <code>docs/</code> <a class="header-anchor" href="#_2-构建到-docs" aria-label="Permalink to &quot;2. 构建到 \`docs/\`&quot;">​</a></h3><p>在项目根目录执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span></span></code></pre></div><p>Windows PowerShell 若提示禁止运行 <code>npm.ps1</code>，改用：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">npm.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> run deploy</span></span></code></pre></div><p>或：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cmd </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;npm run deploy&quot;</span></span></code></pre></div><p>成功后会看到类似：<code>✓ 已复制构建结果到 docs/</code>。</p><h3 id="_3-提交并推送到-github-关键-要带上-docs" tabindex="-1">3. 提交并推送到 GitHub（关键：要带上 <code>docs/</code>） <a class="header-anchor" href="#_3-提交并推送到-github-关键-要带上-docs" aria-label="Permalink to &quot;3. 提交并推送到 GitHub（关键：要带上 \`docs/\`）&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;更新站点内容&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span></code></pre></div><p>只改了源码却<strong>没 push <code>docs/</code></strong>，线上不会变。</p><h3 id="_4-等-pages-生效后访问" tabindex="-1">4. 等 Pages 生效后访问 <a class="header-anchor" href="#_4-等-pages-生效后访问" aria-label="Permalink to &quot;4. 等 Pages 生效后访问&quot;">​</a></h3><ul><li>正式站：<a href="https://milkywaydev.cn" target="_blank" rel="noreferrer">https://milkywaydev.cn</a></li><li>备用查看：仓库 Settings → Pages 里显示的 <code>*.github.io</code> 地址</li></ul><p>一般几十秒到几分钟。若页面还是旧的：无痕窗口、强刷，或等 CDN/浏览器缓存过期。</p><hr><h2 id="四、首次从零配置-新电脑-新仓库才需要" tabindex="-1">四、首次从零配置（新电脑 / 新仓库才需要） <a class="header-anchor" href="#四、首次从零配置-新电脑-新仓库才需要" aria-label="Permalink to &quot;四、首次从零配置（新电脑 / 新仓库才需要）&quot;">​</a></h2><h3 id="_4-1-环境" tabindex="-1">4.1 环境 <a class="header-anchor" href="#_4-1-环境" aria-label="Permalink to &quot;4.1 环境&quot;">​</a></h3><ul><li>安装 <a href="https://nodejs.org/" target="_blank" rel="noreferrer">Node.js</a>（建议 LTS）</li><li>安装 Git，并配置好对本仓库的 SSH 或 HTTPS 登录</li></ul><h3 id="_4-2-拉代码与安装依赖" tabindex="-1">4.2 拉代码与安装依赖 <a class="header-anchor" href="#_4-2-拉代码与安装依赖" aria-label="Permalink to &quot;4.2 拉代码与安装依赖&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git@github.com:FridayIron/milkywaydev.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> milkywaydev</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><h3 id="_4-3-本地预览" tabindex="-1">4.3 本地预览 <a class="header-anchor" href="#_4-3-本地预览" aria-label="Permalink to &quot;4.3 本地预览&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>浏览器打开终端打印的地址（多为 <code>http://localhost:5173</code>）。</p><h3 id="_4-4-开启-github-pages-若仓库还没开" tabindex="-1">4.4 开启 GitHub Pages（若仓库还没开） <a class="header-anchor" href="#_4-4-开启-github-pages-若仓库还没开" aria-label="Permalink to &quot;4.4 开启 GitHub Pages（若仓库还没开）&quot;">​</a></h3><ol><li>先在本地执行一次 <code>npm run deploy</code>，并 push 含 <code>docs/</code> 的提交</li><li>GitHub → Settings → Pages → Branch 选 <code>main</code>，Folder 选 <code>/docs</code> → Save</li><li>填入自定义域名 <code>milkywaydev.cn</code>，按提示配 DNS</li><li>勾选 HTTPS（证书签发可能要等一会儿）</li></ol><hr><h2 id="五、命令速查" tabindex="-1">五、命令速查 <a class="header-anchor" href="#五、命令速查" aria-label="Permalink to &quot;五、命令速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>npm install</code></td><td>安装依赖（新环境 / 依赖变更后）</td></tr><tr><td><code>npm run dev</code></td><td>本地开发预览</td></tr><tr><td><code>npm run build</code></td><td>只构建到 <code>.vitepress/dist</code></td></tr><tr><td><code>npm run deploy</code></td><td>构建并复制到 <code>docs/</code>（<strong>上线前必做</strong>）</td></tr><tr><td><code>npm run preview</code></td><td>本地预览已构建站点（端口多为 4173）</td></tr><tr><td><code>git push origin main</code></td><td>推送后 GitHub Pages 才会更新</td></tr></tbody></table><p><code>npm run deploy</code> 实际做了两件事：</p><ol><li><code>vitepress build</code> → 输出到 <code>.vitepress/dist</code></li><li><code>node scripts/copy-to-docs.cjs</code> → 整目录覆盖复制到 <code>docs/</code></li></ol><hr><h2 id="六、线上不更新时怎么查" tabindex="-1">六、线上不更新时怎么查 <a class="header-anchor" href="#六、线上不更新时怎么查" aria-label="Permalink to &quot;六、线上不更新时怎么查&quot;">​</a></h2><p>按顺序排查：</p><ol><li><strong>本地是否执行了 <code>npm run deploy</code>？</strong><ul><li>只改了 <code>.md</code> 却没 deploy，<code>docs/</code> 仍是旧 HTML。</li></ul></li><li><strong>是否 push 了包含 <code>docs/</code> 的提交？</strong><ul><li>在 GitHub 网页打开仓库，看 <code>docs/</code> 里文件时间/内容是否最新。</li></ul></li><li><strong>Pages 是否指向 <code>/docs</code>？</strong><ul><li>Settings → Pages → Folder 必须是 <strong>/docs</strong>，不是根目录。</li></ul></li><li><strong>分支是否是 <code>main</code>？</strong><ul><li>推错分支 Pages 读不到。</li></ul></li><li><strong>缓存</strong><ul><li>无痕窗口 / <code>Ctrl+F5</code>；自定义域名偶发有短缓存。</li></ul></li><li><strong>构建是否失败</strong><ul><li>本地 <code>npm run deploy</code> 终端有没有报错；有错则 <code>docs/</code> 可能不完整。</li></ul></li></ol><hr><h2 id="七、和腾讯云-cos-的关系" tabindex="-1">七、和腾讯云 COS 的关系 <a class="header-anchor" href="#七、和腾讯云-cos-的关系" aria-label="Permalink to &quot;七、和腾讯云 COS 的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>作用</th><th>是否当前主路径</th></tr></thead><tbody><tr><td><strong>GitHub Pages + <code>/docs</code></strong></td><td>推送后公网可访问</td><td><strong>是（当前正式）</strong></td></tr><tr><td>腾讯云 COS</td><td>把 <code>docs/</code> 再上传到对象存储</td><td>可选备用，见 <code>腾讯云部署说明.md</code></td></tr></tbody></table><p>日常以 <strong>GitHub 推送 <code>docs/</code></strong> 为准即可。COS 只有在你刻意双写/切流量时才需要再上传一遍。</p><hr><h2 id="八、不要做的事" tabindex="-1">八、不要做的事 <a class="header-anchor" href="#八、不要做的事" aria-label="Permalink to &quot;八、不要做的事&quot;">​</a></h2><ul><li>不要手改 <code>docs/</code> 里的 HTML 当「正式改站」——下次 <code>deploy</code> 会覆盖。</li><li>不要只提交源码、不提交 <code>docs/</code> 却指望线上更新。</li><li>不要把 Pages Folder 改成 <code>/</code>（根目录），除非同时改掉整套输出路径。</li><li>不要把含密钥的 <code>.env</code> 之类提交进仓库（本博客静态站一般不需要）。</li></ul><hr><h2 id="九、一句话备忘" tabindex="-1">九、一句话备忘 <a class="header-anchor" href="#九、一句话备忘" aria-label="Permalink to &quot;九、一句话备忘&quot;">​</a></h2><p><strong>改完 → <code>npm run deploy</code> → <code>git push</code>（带上 <code>docs/</code>）→ 打开 <a href="https://milkywaydev.cn" target="_blank" rel="noreferrer">https://milkywaydev.cn</a></strong></p>`,66)])])}const u=s(d,[["render",o]]);export{g as __pageData,u as default};
